import fs from "node:fs";

const regions = ["north", "south", "east", "west"];
const fails = [];
const ok = (cond, msg) => { if (!cond) fails.push(msg); };

const answer = JSON.parse(fs.readFileSync("answer.json", "utf8"));

// --- top-level shape ---
ok(answer && typeof answer === "object" && !Array.isArray(answer), "answer.json is not a JSON object");
const topKeys = Object.keys(answer).sort();
ok(JSON.stringify(topKeys) === JSON.stringify(["grand_units","grand_weighted","regions"]),
   `unexpected top-level keys: ${JSON.stringify(topKeys)}`);

ok(answer.regions && typeof answer.regions === "object" && !Array.isArray(answer.regions),
   "regions missing or not an object");
const regionKeys = Object.keys(answer.regions || {}).sort();
ok(JSON.stringify(regionKeys) === JSON.stringify([...regions].sort()),
   `regions keys are ${JSON.stringify(regionKeys)}, expected exactly north/south/east/west`);

// --- recompute from the four sources ---
let allUnits = 0, allWeighted = 0, allCount = 0;

for (const r of regions) {
  const rows = JSON.parse(fs.readFileSync(`${r}.json`, "utf8"));
  ok(Array.isArray(rows) && rows.length > 0, `${r}.json is not a non-empty array`);
  for (const [i, row] of rows.entries()) {
    ok(row && typeof row.units === "number" && Number.isFinite(row.units), `${r}[${i}].units not a finite number`);
    ok(row && typeof row.weight === "number" && Number.isFinite(row.weight), `${r}[${i}].weight not a finite number`);
  }
  const count = rows.length;
  const units = rows.reduce((s, x) => s + x.units, 0);
  const weighted = rows.reduce((s, x) => s + x.units * x.weight, 0);

  allCount += count; allUnits += units; allWeighted += weighted;

  const e = answer.regions?.[r];
  ok(e && typeof e === "object" && !Array.isArray(e), `regions.${r} missing or not an object`);
  const eKeys = e ? Object.keys(e).sort() : [];
  ok(JSON.stringify(eKeys) === JSON.stringify(["count","units","weighted"]),
     `regions.${r} keys are ${JSON.stringify(eKeys)}, expected exactly count/units/weighted`);
  ok(e?.count === count, `regions.${r}.count is ${e?.count}, recomputed ${count}`);
  ok(e?.units === units, `regions.${r}.units is ${e?.units}, recomputed ${units}`);
  ok(e?.weighted === weighted, `regions.${r}.weighted is ${e?.weighted}, recomputed ${weighted}`);

  const sumCount = regions.reduce((s, k) => s + (answer.regions?.[k]?.count ?? 0), 0);
  console.log(`${r}: count=${count} units=${units} weighted=${weighted}  (answer: ${e?.count}/${e?.units}/${e?.weighted})`);
}

// --- grand totals: both as sum of regions and over all 40 source records ---
const regionSumUnits = regions.reduce((s, k) => s + (answer.regions?.[k]?.units ?? 0), 0);
const regionSumWeighted = regions.reduce((s, k) => s + (answer.regions?.[k]?.weighted ?? 0), 0);

ok(typeof answer.grand_units === "number" && Number.isFinite(answer.grand_units), "grand_units not a finite number");
ok(typeof answer.grand_weighted === "number" && Number.isFinite(answer.grand_weighted), "grand_weighted not a finite number");
ok(answer.grand_units === allUnits, `grand_units is ${answer.grand_units}, recomputed from sources ${allUnits}`);
ok(answer.grand_weighted === allWeighted, `grand_weighted is ${answer.grand_weighted}, recomputed from sources ${allWeighted}`);
ok(answer.grand_units === regionSumUnits, `grand_units ${answer.grand_units} != sum of regions ${regionSumUnits}`);
ok(answer.grand_weighted === regionSumWeighted, `grand_weighted ${answer.grand_weighted} != sum of regions ${regionSumWeighted}`);

const totalCount = regions.reduce((s, k) => s + (answer.regions?.[k]?.count ?? 0), 0);
ok(allCount === totalCount, `source record total ${allCount} != region count total ${totalCount}`);

console.log(`grand_units=${answer.grand_units} grand_weighted=${answer.grand_weighted} records=${allCount}`);

if (fails.length) {
  console.error("\nFAILURES:");
  for (const f of fails) console.error(" - " + f);
  console.error(`RESULT: FAIL (${fails.length} assertion(s))`);
  process.exit(1);
}
console.log("RESULT: PASS - answer.json complete and every value matches the four sources");
